{
  "narratives": [
    {
      "item_code": "S5_MEDIA",
      "title_raw": "가. 적절한(부적절한) 소화제",
      "start": "p3:L30",
      "end": "p3:L41"
    },
    {
      "item_code": "S5_SPECIFIC",
      "title_raw": "나. 화학물질로부터 생기는 특정 유해성",
      "start": "p4:L1",
      "end": "p4:L13"
    },
    {
      "item_code": "S5_FIREFIGHT",
      "title_raw": "다. 화재진압시 착용할 보호구 및 예방조치",
      "start": "p4:L16",
      "end": "p4:L27"
    }
  ],
  "extras": [
    {
      "after_item": "S5_MEDIA",
      "title_raw": "○ 적절한 소화제",
      "reason": "코드없음",
      "statements": [
        {
          "key": "적절한 소화제",
          "value": "CO2"
        ,
        "line": "p3:L32"
        },
        {
          "key": "적절한 소화제",
          "value": "건조화학제"
        ,
        "line": "p3:L33"
        },
        {
          "key": "적절한 소화제",
          "value": "내알콜포말(알코올 또는 극성용매 혼합물의 경우)"
        ,
        "line": "p3:L34"
        },
        {
          "key": "적절한 소화제",
          "value": "물분무"
        ,
        "line": "p3:L35"
        },
        {
          "key": "적절한 소화제",
          "value": "이 물질과 관련된 소화시 알콜 포말, 이산화탄소 또는 물분무를 사용할 것."
        ,
        "line": "p3:L36"
        },
        {
          "key": "적절한 소화제",
          "value": "일반포말"
        ,
        "line": "p3:L37"
        },
        {
          "key": "적절한 소화제",
          "value": "질식소화시 건조한 모래 또는 흙을 사용할 것."
        ,
        "line": "p3:L38"
        }
      ]
    ,
    "line": "p3:L31"
    },
    {
      "after_item": "S5_MEDIA",
      "title_raw": "○ 부적절한 소화제",
      "reason": "코드없음",
      "statements": [
        {
          "key": "부적절한 소화제",
          "value": "고압주수"
        ,
        "line": "p3:L40"
        },
        {
          "key": "부적절한 소화제",
          "value": "직접주수"
        ,
        "line": "p3:L41"
        }
      ]
    ,
    "line": "p3:L39"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "○ 열분해성 생성물",
      "reason": "코드없음",
      "statements": [
        {
          "key": "열분해성 생성물",
          "value": "타는 동안 열분해 또는 연소에 의해 자극적이고 매우 유독한 가스가 발생될 수 있음."
        ,
        "line": "p4:L2"
        }
      ]
    ,
    "line": "p4:L1"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "○ 화재 및 폭발 위험",
      "reason": "코드없음",
      "statements": [
        {
          "key": "화재 및 폭발 위험",
          "value": "가열시 용기가 폭발할 수 있음."
        ,
        "line": "p4:L4"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "가열시 증기는 공기와 혼합하여 폭발성 혼합물을 형성할 수 있음; 실내, 실외, 하수구에 폭발 위험."
        ,
        "line": "p4:L5"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "격렬하게 중합반응하여 화재와 폭발을 일으킬 수 있음."
        ,
        "line": "p4:L6"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "고인화성; 열, 스파크, 화염에 의해 쉽게 점화됨."
        ,
        "line": "p4:L7"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "누출물은 화재/폭발 위험이 있음."
        ,
        "line": "p4:L8"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "실내, 실외, 하수구에서 증기 폭발 위험이 있음."
        ,
        "line": "p4:L9"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "인화점이나 그 이상에서 폭발성 혼합물을 형성할 수 있음."
        ,
        "line": "p4:L10"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "일부는 탈 수 있으나 쉽게 점화하지 않음."
        ,
        "line": "p4:L11"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "증기는 공기와 폭발성 혼합물을 형성할 수 있음."
        ,
        "line": "p4:L12"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "증기는 점화원까지 이동하여 역화(flash back)할 수 있음."
        ,
        "line": "p4:L13"
        }
      ]
    ,
    "line": "p4:L3"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "○ 기타",
      "reason": "코드없음",
      "statements": [
        {
          "key": "기타",
          "value": "증기는 자각 없이 현기증 또는 질식을 유발할 수 있음."
        ,
        "line": "p4:L15"
        }
      ]
    ,
    "line": "p4:L14"
    }
  ]
}

